  3	import com.fasterxml.jackson.databind.ObjectMapper;
  4	import com.fasterxml.jackson.databind.SerializationFeature;
  5	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  6	import com.pousadamareaalta.api.ApiController;
  7	import com.pousadamareaalta.repository.Database;
  8	import com.pousadamareaalta.repository.MessageRepository;
  9	import com.pousadamareaalta.repository.ReservationRepository;
 10	import com.pousadamareaalta.service.MessageService;
 11	import com.pousadamareaalta.service.ReportService;
 12	import com.pousadamareaalta.service.ReservationService;
 13	import com.pousadamareaalta.service.RoomService;
 14	import io.javalin.Javalin;
 15	import io.javalin.json.JavalinJackson;
 16	
 17	public class App {
 18	
 19	    public static void main(String[] args) {
 20	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 21	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
 22	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
 23	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 24	
 25	        Database database = new Database(dbUrl, dbUser, dbPassword);
 26	
 27	        ReservationRepository reservationRepository = new ReservationRepository(database);
 28	        MessageRepository messageRepository = new MessageRepository(database);
 29	
 30	        RoomService roomService = new RoomService();
 31	        MessageService messageService = new MessageService(messageRepository);
 32	        ReservationService reservationService = new ReservationService(reservationRepository, roomService, messageService);
 33	        ReportService reportService = new ReportService(reservationRepository, roomService);
 34	
 35	        ApiController apiController = new ApiController(roomService, reservationService, messageService, reportService);
 36	
 37	        ObjectMapper objectMapper = new ObjectMapper();
 38	        objectMapper.registerModule(new JavaTimeModule());
 39	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 40	
 41	        Javalin app = Javalin.create(config -> {
 42	            config.jsonMapper(new JavalinJackson(objectMapper, false));
 43	        }).start(port);
 44	
 45	        apiController.registerRoutes(app);
 46	
 47	        System.out.println("Pousada Maré Alta - Sistema de Reservas");
 48	        System.out.println("Server started on port " + port);
 49	    }
 50	}
 51	package com.pousadamareaalta.api;
 52	
 53	import com.pousadamareaalta.api.dto.*;
 54	import com.pousadamareaalta.exception.*;
 55	import com.pousadamareaalta.model.RatePlan;
