 61	import io.javalin.Javalin;
 62	import io.javalin.http.Context;
 63	
 64	import java.time.LocalDate;
 65	import java.time.YearMonth;
 66	import java.time.format.DateTimeFormatter;
 67	import java.time.format.DateTimeParseException;
 68	
 69	public class ApiController {
 70	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 71	    private static final DateTimeFormatter MONTH_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM");
 72	
 73	    private final RoomService roomService;
 74	    private final ReservationService reservationService;
 75	    private final MessageService messageService;
 76	    private final ReportService reportService;
 77	    private final ApiMapper mapper;
 78	
 79	    public ApiController(RoomService roomService, ReservationService reservationService,
 80	                        MessageService messageService, ReportService reportService) {
 81	        this.roomService = roomService;
 82	        this.reservationService = reservationService;
 83	        this.messageService = messageService;
 84	        this.reportService = reportService;
 85	        this.mapper = new ApiMapper(roomService);
 86	    }
 87	
 88	    public void registerRoutes(Javalin app) {
 89	        app.get("/rooms", this::getRooms);
 90	        app.post("/reservations", this::createReservation);
 91	        app.get("/reservations/{id}", this::getReservation);
 92	        app.post("/reservations/{id}/confirmation", this::confirmReservation);
 93	        app.post("/reservations/{id}/cancellation", this::cancelReservation);
 94	        app.post("/reservations/{id}/check-in", this::checkIn);
 95	        app.post("/reservations/{id}/check-out", this::checkOut);
 96	        app.get("/reservations/{id}/document", this::getDocument);
 97	        app.get("/messages", this::getMessages);
 98	        app.get("/reports/occupancy", this::getOccupancyReport);
 99	        app.get("/reports/revenue", this::getRevenueReport);
100	
101	        app.exception(InvalidRequestException.class, (e, ctx) -> {
102	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
103	        });
104	
105	        app.exception(RoomNotFoundException.class, (e, ctx) -> {
106	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
107	        });
108	
109	        app.exception(ReservationNotFoundException.class, (e, ctx) -> {
110	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
111	        });
112	
113	        app.exception(RoomUnavailableException.class, (e, ctx) -> {
114	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
115	        });
116	
117	        app.exception(OperationNotAllowedException.class, (e, ctx) -> {
118	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
119	        });
120	
121	        app.exception(CapacityExceededException.class, (e, ctx) -> {
122	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
123	        });
124	    }
125	
126	    private void getRooms(Context ctx) {
127	        var rooms = roomService.getAllRooms().stream()
128	            .map(mapper::toRoomDTO)
129	            .toList();
130	        ctx.json(rooms);
131	    }
132	
133	    private void createReservation(Context ctx) {
134	        try {
135	            CreateReservationRequest req = ctx.bodyAsClass(CreateReservationRequest.class);
136	
137	            LocalDate checkIn = LocalDate.parse(req.checkIn(), DATE_FORMATTER);
138	            LocalDate checkOut = LocalDate.parse(req.checkOut(), DATE_FORMATTER);
139	            RatePlan ratePlan = RatePlan.valueOf(req.ratePlan());
140	
141	            Reservation reservation = reservationService.createReservation(
142	                req.roomNumber(),
143	                req.guestName(),
144	                req.guestEmail(),
145	                req.guestCpf(),
146	                checkIn,
147	                checkOut,
148	                req.guests(),
149	                ratePlan,
150	                req.companyCode()
151	            );
152	
153	            ctx.status(201).json(mapper.toReservationDTO(reservation));
154	        } catch (DateTimeParseException | IllegalArgumentException e) {
155	            throw new InvalidRequestException("Invalid request data");
156	        }
157	    }
158	
159	    private void getReservation(Context ctx) {
160	        long id = Long.parseLong(ctx.pathParam("id"));
161	        Reservation reservation = reservationService.getReservation(id);
162	        ctx.json(mapper.toReservationDTO(reservation));
163	    }
164	
165	    private void confirmReservation(Context ctx) {
166	        long id = Long.parseLong(ctx.pathParam("id"));
167	        Reservation reservation = reservationService.confirmReservation(id);
168	        ctx.json(mapper.toReservationDTO(reservation));
169	    }
170	
171	    private void cancelReservation(Context ctx) {
172	        long id = Long.parseLong(ctx.pathParam("id"));
173	        Reservation reservation = reservationService.cancelReservation(id);
174	        ctx.json(mapper.toReservationDTO(reservation));
175	    }
176	
177	    private void checkIn(Context ctx) {
178	        long id = Long.parseLong(ctx.pathParam("id"));
179	        Reservation reservation = reservationService.checkIn(id);
180	        ctx.json(mapper.toReservationDTO(reservation));
181	    }
182	
183	    private void checkOut(Context ctx) {
184	        long id = Long.parseLong(ctx.pathParam("id"));
185	        Reservation reservation = reservationService.checkOut(id);
186	        ctx.json(mapper.toReceiptDTO(reservation));
187	    }
188	
189	    private void getDocument(Context ctx) {
190	        long id = Long.parseLong(ctx.pathParam("id"));
191	        Reservation reservation = reservationService.getReservation(id);
192	        ctx.json(mapper.toReceiptDTO(reservation));
193	    }
194	
195	    private void getMessages(Context ctx) {
196	        var messages = messageService.getAllMessages().stream()
197	            .map(mapper::toMessageDTO)
198	            .toList();
199	        ctx.json(messages);
200	    }
201	
202	    private void getOccupancyReport(Context ctx) {
203	        try {
204	            String dateStr = ctx.queryParam("date");
205	            if (dateStr == null) {
206	                throw new InvalidRequestException("Date parameter is required");
207	            }
208	
209	            LocalDate date = LocalDate.parse(dateStr, DATE_FORMATTER);
210	            String csv = reportService.generateOccupancyReport(date);
211	
212	            ctx.contentType("text/csv; charset=utf-8").result(csv);
213	        } catch (DateTimeParseException e) {
214	            throw new InvalidRequestException("Invalid date format");
215	        }
216	    }
217	
218	    private void getRevenueReport(Context ctx) {
219	        try {
220	            String monthStr = ctx.queryParam("month");
221	            if (monthStr == null) {
222	                throw new InvalidRequestException("Month parameter is required");
223	            }
224	
225	            YearMonth yearMonth = YearMonth.parse(monthStr, MONTH_FORMATTER);
226	            String csv = reportService.generateRevenueReport(yearMonth.getYear(), yearMonth.getMonthValue());
227	
228	            ctx.contentType("text/csv; charset=utf-8").result(csv);
229	        } catch (DateTimeParseException e) {
230	            throw new InvalidRequestException("Invalid month format");
231	        }
232	    }
233	}
