112	import com.pousadamareaalta.pricing.RatePlanStrategy;
113	import com.pousadamareaalta.repository.ReservationRepository;
114	
115	import java.math.BigDecimal;
116	import java.time.LocalDate;
117	import java.time.format.DateTimeFormatter;
118	import java.time.temporal.ChronoUnit;
119	import java.util.List;
120	
121	public class ReservationService {
122	    private final ReservationRepository reservationRepository;
123	    private final RoomService roomService;
124	    private final MessageService messageService;
125	
126	    public ReservationService(ReservationRepository reservationRepository, RoomService roomService, MessageService messageService) {
127	        this.reservationRepository = reservationRepository;
128	        this.roomService = roomService;
129	        this.messageService = messageService;
130	    }
131	
132	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
133	                                        LocalDate checkIn, LocalDate checkOut, int guests,
134	                                        com.pousadamareaalta.model.RatePlan ratePlan, String companyCode) {
135	
136	        Room room = roomService.getRoom(roomNumber);
137	
138	        if (guests < 1) {
139	            throw new InvalidRequestException("At least one guest is required");
140	        }
141	
142	        if (guests > room.getCapacity()) {
143	            throw new CapacityExceededException("Room capacity exceeded");
144	        }
145	
146	        if (!checkOut.isAfter(checkIn)) {
147	            throw new InvalidRequestException("Check-out must be after check-in");
148	        }
149	
150	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
151	
152	        RatePlanStrategy strategy = RatePlanFactory.getStrategy(ratePlan);
153	        strategy.validate(checkIn, checkOut, nights, companyCode);
154	
155	        List<Reservation> conflicts = reservationRepository.findConflicting(roomNumber, checkIn, checkOut, null);
156	        if (!conflicts.isEmpty()) {
157	            throw new RoomUnavailableException("Room is not available for the selected dates");
158	        }
159	
160	        PricingResult pricing = strategy.calculatePrice(room.getType(), checkIn, checkOut, nights, companyCode);
161	
162	        Reservation reservation = new Reservation();
163	        reservation.setRoomNumber(roomNumber);
164	        reservation.setGuestName(guestName);
165	        reservation.setGuestEmail(guestEmail);
166	        reservation.setGuestCpf(guestCpf);
167	        reservation.setCheckIn(checkIn);
168	        reservation.setCheckOut(checkOut);
169	        reservation.setGuests(guests);
170	        reservation.setRatePlan(ratePlan);
171	        reservation.setCompanyCode(companyCode);
172	        reservation.setNights(nights);
173	        reservation.setSubtotal(pricing.getSubtotal());
174	        reservation.setDiscount(pricing.getDiscount());
175	        reservation.setTotal(pricing.getTotal());
176	        reservation.setStatus(ReservationStatus.PENDING);
177	        reservation.setAmountPaid(BigDecimal.ZERO);
178	        reservation.setRefund(null);
179	
180	        return reservationRepository.save(reservation);
181	    }
182	
183	    public Reservation getReservation(Long id) {
184	        return reservationRepository.findById(id)
185	            .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
186	    }
187	
188	    public Reservation confirmReservation(Long id) {
189	        Reservation reservation = getReservation(id);
190	
191	        if (reservation.getStatus() != ReservationStatus.PENDING) {
192	            throw new OperationNotAllowedException("Only pending reservations can be confirmed");
193	        }
194	
195	        reservation.setStatus(ReservationStatus.CONFIRMED);
196	        reservation.setAmountPaid(reservation.getTotal());
197	
198	        reservationRepository.save(reservation);
199	
200	        sendConfirmationEmail(reservation);
201	
202	        return reservation;
203	    }
204	
205	    public Reservation cancelReservation(Long id) {
206	        Reservation reservation = getReservation(id);
207	
208	        if (reservation.getStatus() != ReservationStatus.PENDING &&
209	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
210	            throw new OperationNotAllowedException("Cannot cancel reservation after check-in");
211	        }
212	
213	        RatePlanStrategy strategy = RatePlanFactory.getStrategy(reservation.getRatePlan());
214	        BigDecimal refundAmount = strategy.calculateRefund(reservation.getAmountPaid());
215	
216	        reservation.setStatus(ReservationStatus.CANCELLED);
217	        reservation.setRefund(refundAmount);
218	
219	        return reservationRepository.save(reservation);
220	    }
221	
222	    public Reservation checkIn(Long id) {
223	        Reservation reservation = getReservation(id);
224	
225	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
226	            throw new OperationNotAllowedException("Only confirmed reservations can be checked in");
227	        }
228	
229	        reservation.setStatus(ReservationStatus.CHECKED_IN);
230	
231	        return reservationRepository.save(reservation);
232	    }
233	
234	    public Reservation checkOut(Long id) {
235	        Reservation reservation = getReservation(id);
236	
237	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
238	            throw new OperationNotAllowedException("Only checked-in reservations can be checked out");
239	        }
240	
241	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
242	
243	        return reservationRepository.save(reservation);
244	    }
245	
246	    private void sendConfirmationEmail(Reservation reservation) {
247	        String receipt = generateReceipt(reservation);
248	        String subject = "Reserva confirmada - Pousada Maré Alta";
249	        String body = String.format("""
250	            Olá, %s!
251	
252	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
253	
254	            %s
255	
256	            A entrada é a partir das 14h, e a saída, até as 12h.
257	            Até breve!
258	            """, reservation.getGuestName(), receipt);
259	
260	        messageService.sendEmail(reservation.getGuestEmail(), subject, body);
261	    }
262	
263	    public String generateReceipt(Reservation reservation) {
264	        if (reservation.getStatus() == ReservationStatus.PENDING) {
265	            throw new OperationNotAllowedException("Receipt is only available for paid reservations");
266	        }
267	
268	        Room room = roomService.getRoom(reservation.getRoomNumber());
269	        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
270	
271	        StringBuilder receipt = new StringBuilder();
272	        receipt.append(String.format("Comprovante de reserva nº %d%n", reservation.getId()));
273	        receipt.append(String.format("Hóspede: %s (CPF %s)%n", reservation.getGuestName(), reservation.getGuestCpf()));
274	        receipt.append(String.format("Quarto: %d (%s)%n", reservation.getRoomNumber(), room.getType().name()));
275	        receipt.append(String.format("Entrada: %s | Saída: %s | %d %s%n",
276	            reservation.getCheckIn().format(formatter),
277	            reservation.getCheckOut().format(formatter),
278	            reservation.getNights(),
279	            reservation.getNights() == 1 ? "diária" : "diárias"));
280	        receipt.append(String.format("Diárias: R$ %s%n", formatMoney(reservation.getSubtotal())));
281	
282	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
283	            receipt.append(String.format("Desconto: R$ %s%n", formatMoney(reservation.getDiscount())));
284	        }
285	
286	        receipt.append(String.format("Total: R$ %s", formatMoney(reservation.getTotal())));
287	
288	        return receipt.toString();
289	    }
290	
291	    private String formatMoney(BigDecimal amount) {
292	        return String.format("%,.2f", amount).replace(",", "X").replace(".", ",").replace("X", ".");
293	    }
294	}
