272	                stmt.setLong(4, excludeId);
273	                stmt.setLong(5, excludeId);
274	            } else {
275	                stmt.setNull(4, Types.BIGINT);
276	                stmt.setNull(5, Types.BIGINT);
277	            }
278	
279	            List<Reservation> reservations = new ArrayList<>();
280	            try (ResultSet rs = stmt.executeQuery()) {
281	                while (rs.next()) {
282	                    reservations.add(mapReservation(rs));
283	                }
284	            }
285	
286	            return reservations;
287	        } catch (SQLException e) {
288	            throw new RuntimeException("Failed to find conflicting reservations", e);
289	        }
290	    }
291	
292	    public List<Reservation> findByDateAndStatus(LocalDate date) {
293	        String sql = """
294	            SELECT * FROM reservations
295	            WHERE check_in <= ?
296	            AND check_out > ?
297	            AND status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
298	            ORDER BY room_number
299	        """;
300	
301	        try (Connection conn = database.getConnection();
302	             PreparedStatement stmt = conn.prepareStatement(sql)) {
303	
304	            stmt.setDate(1, Date.valueOf(date));
305	            stmt.setDate(2, Date.valueOf(date));
306	
307	            List<Reservation> reservations = new ArrayList<>();
308	            try (ResultSet rs = stmt.executeQuery()) {
309	                while (rs.next()) {
310	                    reservations.add(mapReservation(rs));
311	                }
312	            }
313	
314	            return reservations;
315	        } catch (SQLException e) {
316	            throw new RuntimeException("Failed to find reservations by date", e);
317	        }
318	    }
319	
320	    public List<Reservation> findByMonth(int year, int month) {
321	        String sql = """
322	            SELECT * FROM reservations
323	            WHERE EXTRACT(YEAR FROM check_in) = ?
324	            AND EXTRACT(MONTH FROM check_in) = ?
325	            ORDER BY check_in, id
326	        """;
327	
328	        try (Connection conn = database.getConnection();
329	             PreparedStatement stmt = conn.prepareStatement(sql)) {
330	
331	            stmt.setInt(1, year);
332	            stmt.setInt(2, month);
333	
334	            List<Reservation> reservations = new ArrayList<>();
335	            try (ResultSet rs = stmt.executeQuery()) {
336	                while (rs.next()) {
337	                    reservations.add(mapReservation(rs));
338	                }
339	            }
340	
341	            return reservations;
342	        } catch (SQLException e) {
343	            throw new RuntimeException("Failed to find reservations by month", e);
344	        }
345	    }
346	
347	    private Reservation mapReservation(ResultSet rs) throws SQLException {
348	        Reservation r = new Reservation();
349	        r.setId(rs.getLong("id"));
350	        r.setRoomNumber(rs.getInt("room_number"));
351	        r.setGuestName(rs.getString("guest_name"));
352	        r.setGuestEmail(rs.getString("guest_email"));
353	        r.setGuestCpf(rs.getString("guest_cpf"));
354	        r.setCheckIn(rs.getDate("check_in").toLocalDate());
355	        r.setCheckOut(rs.getDate("check_out").toLocalDate());
356	        r.setGuests(rs.getInt("guests"));
357	        r.setRatePlan(RatePlan.valueOf(rs.getString("rate_plan")));
358	        r.setCompanyCode(rs.getString("company_code"));
359	        r.setNights(rs.getInt("nights"));
360	        r.setSubtotal(rs.getBigDecimal("subtotal"));
361	        r.setDiscount(rs.getBigDecimal("discount"));
362	        r.setTotal(rs.getBigDecimal("total"));
363	        r.setStatus(ReservationStatus.valueOf(rs.getString("status")));
364	        r.setAmountPaid(rs.getBigDecimal("amount_paid"));
365	        BigDecimal refund = rs.getBigDecimal("refund");
366	        r.setRefund(rs.wasNull() ? null : refund);
367	        return r;
368	    }
369	}

