     1	package com.pousadamareaalta.pricing;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	
     7	public class SeasonUtil {
     8	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
     9	
    10	    public static boolean isHighSeason(LocalDate date) {
    11	        int month = date.getMonthValue();
    12	        int day = date.getDayOfMonth();
    13	
    14	        if (month == 12 && day >= 15) {
    15	            return true;
    16	        }
    17	
    18	        if (month == 1 || month == 2) {
    19	            return true;
    20	        }
    21	
    22	        if (month == 7) {
    23	            return true;
    24	        }
    25	
    26	        return false;
    27	    }
    28	
    29	    public static BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate date) {
    30	        if (isHighSeason(date)) {
    31	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, RoundingMode.HALF_EVEN);
    32	        }
    33	        return baseRate;
    34	    }
    35	
    36	    public static BigDecimal round(BigDecimal value) {
    37	        return value.setScale(2, RoundingMode.HALF_EVEN);
    38	    }
    39	}
