     8	public class StandardRatePlan implements RatePlanStrategy {
     9	
    10	    @Override
    11	    public void validate(LocalDate checkIn, LocalDate checkOut, int nights, String companyCode) {
    12	    }
    13	
    14	    @Override
    15	    public PricingResult calculatePrice(RoomType roomType, LocalDate checkIn, LocalDate checkOut, int nights, String companyCode) {
    16	        BigDecimal subtotal = calculateSubtotal(roomType, checkIn, nights);
    17	        BigDecimal discount = BigDecimal.ZERO;
    18	        BigDecimal total = subtotal;
    19	
    20	        return new PricingResult(subtotal, discount, total);
    21	    }
    22	
    23	    @Override
    24	    public BigDecimal calculateRefund(BigDecimal amountPaid) {
    25	        return amountPaid;
    26	    }
    27	
    28	    protected BigDecimal calculateSubtotal(RoomType roomType, LocalDate checkIn, int nights) {
    29	        BigDecimal subtotal = BigDecimal.ZERO;
    30	        LocalDate currentDate = checkIn;
    31	
    32	        for (int i = 0; i < nights; i++) {
    33	            BigDecimal nightPrice = SeasonUtil.calculateNightPrice(roomType.getNightlyRate(), currentDate);
    34	            subtotal = subtotal.add(nightPrice);
    35	            currentDate = currentDate.plusDays(1);
    36	        }
    37	
    38	        return SeasonUtil.round(subtotal);
    39	    }
    40	}
