     8	import java.time.LocalDate;
     9	import java.util.Map;
    10	
    11	public class WeekendPackageRatePlan implements RatePlanStrategy {
    12	    private static final Map<RoomType, BigDecimal> PACKAGE_PRICES = Map.of(
    13	        RoomType.STANDARD, new BigDecimal("520.00"),
    14	        RoomType.DELUXE, new BigDecimal("820.00"),
    15	        RoomType.SUITE, new BigDecimal("1200.00")
    16	    );
    17	
    18	    private static final BigDecimal REFUND_RATE = new BigDecimal("0.50");
    19	
    20	    @Override
    21	    public void validate(LocalDate checkIn, LocalDate checkOut, int nights, String companyCode) {
    22	        if (nights != 2) {
    23	            throw new InvalidRequestException("Weekend package requires exactly 2 nights");
    24	        }
    25	        if (checkIn.getDayOfWeek() != DayOfWeek.FRIDAY) {
    26	            throw new InvalidRequestException("Weekend package must start on Friday");
    27	        }
    28	        if (checkOut.getDayOfWeek() != DayOfWeek.SUNDAY) {
    29	            throw new InvalidRequestException("Weekend package must end on Sunday");
    30	        }
    31	    }
    32	
    33	    @Override
    34	    public PricingResult calculatePrice(RoomType roomType, LocalDate checkIn, LocalDate checkOut, int nights, String companyCode) {
    35	        BigDecimal packagePrice = PACKAGE_PRICES.get(roomType);
    36	        return new PricingResult(packagePrice, BigDecimal.ZERO, packagePrice);
    37	    }
    38	
    39	    @Override
    40	    public BigDecimal calculateRefund(BigDecimal amountPaid) {
    41	        return SeasonUtil.round(amountPaid.multiply(REFUND_RATE));
    42	    }
    43	}

